styles = {'terminal':'ellipse;whiteSpace=wrap;html=1;fillColor=#d5e8d4;strokeColor=#4a825b;', 'process':'rounded=0;whiteSpace=wrap;html=1;fillColor=#dae8fc;strokeColor=#6c8ebf;', 'decision':'rhombus;whiteSpace=wrap;html=1;fillColor=#fff2cc;strokeColor=#d6b656;', 'input':'shape=parallelogram;perimeter=parallelogramPerimeter;whiteSpace=wrap;html=1;fillColor=#e1d5e7;strokeColor=#9673a6;', 'output':'shape=parallelogram;perimeter=parallelogramPerimeter;whiteSpace=wrap;html=1;fillColor=#e1d5e7;strokeColor=#9673a6;', 'data':'shape=parallelogram;perimeter=parallelogramPerimeter;whiteSpace=wrap;html=1;fillColor=#e1d5e7;strokeColor=#9673a6;', 'database':'shape=cylinder3;whiteSpace=wrap;html=1;boundedLbl=1;fillColor=#f8cecc;strokeColor=#b85450;', 'off':'shape=offPageConnector;whiteSpace=wrap;html=1;fillColor=#f5f5f5;strokeColor=#666666;'}
mxfile = ET.Element('mxfile', {'host':'app.diagrams.net','type':'device'})
for page_id, (title,nodes,edges) in enumerate(pages):
    diagram=ET.SubElement(mxfile,'diagram',{'id':str(page_id+1),'name':title})
    graph=ET.SubElement(diagram,'mxGraphModel',{'dx':'1600','dy':'1100','grid':'1','gridSize':'10','page':'1','pageScale':'1','pageWidth':'1680','pageHeight':'2200','background':'#ffffff'})
    root=ET.SubElement(graph,'root'); ET.SubElement(root,'mxCell',{'id':'0'}); ET.SubElement(root,'mxCell',{'id':'1','parent':'0'})
    for id,label,kind,col,row in nodes:
        cell=ET.SubElement(root,'mxCell',{'id':id,'value':label,'style':styles[kind]+'fontSize=14;spacing=8;','vertex':'1','parent':'1'})
        ET.SubElement(cell,'mxGeometry',{'x':str(35+col*355),'y':str(35+row*140),'width':'290','height':'80','as':'geometry'})
    if title == '03 B Home':
        edges = [(src, dst, label) for src, dst, label in edges if (src, dst) != ('read', 'cache')]
        edges += [('read', 'on1', ''), ('on2', 'cache', '')]
        for key, y in [('on1', 190), ('on2', 315)]:
            cell = ET.SubElement(root, 'mxCell', {'id': key, 'value': 'A', 'style': 'ellipse;whiteSpace=wrap;html=1;fillColor=#ffffff;strokeColor=#666666;fontSize=13;', 'vertex': '1', 'parent': '1'})
            ET.SubElement(cell, 'mxGeometry', {'x':'710', 'y':str(y), 'width':'38', 'height':'38', 'as':'geometry'})
    for index,(src,dst,label) in enumerate(edges):
        edge=ET.SubElement(root,'mxCell',{'id':'edge'+str(index),'value':label,'style':'edgeStyle=orthogonalEdgeStyle;rounded=0;orthogonalLoop=1;jettySize=auto;html=1;endArrow=block;endFill=1;fontSize=12;','edge':'1','parent':'1','source':src,'target':dst})
        ET.SubElement(edge,'mxGeometry',{'relative':'1','as':'geometry'})
    legend=ET.SubElement(root,'mxCell',{'id':'legend','value':'Legend: oval = start/end; rectangle = process; diamond = decision; parallelogram = input/output or data; cylinder = database; pentagon = off-page reference; paired small circles = on-page connector. Arrows show flow; branch labels describe conditions.','style':'text;html=1;whiteSpace=wrap;align=left;verticalAlign=top;fontSize=12;fontColor=#555555;','vertex':'1','parent':'1'})
    ET.SubElement(legend,'mxGeometry',{'x':'35','y':str(35+(max(n[4] for n in nodes)+1)*140),'width':'1360','height':'60','as':'geometry'})
(OUT/'PhysiqueQuest_System_Flowchart.drawio').write_bytes(minidom.parseString(ET.tostring(mxfile,encoding='utf-8')).toprettyxml(indent='  ',encoding='UTF-8'))

modules = [
('Scope and reading guide', ['This inventory describes code present in the workspace on 29 October 2026, including uncommitted work. It is a code inspection, not proof that every provider or deployment is operational.', 'The draw.io document uses linked-by-label off-page references A-G and C1. A node groups related operations; it is not a sequence diagram or a guarantee that all branches are reachable in a particular deployment.']),
('1. Launch, web and mobile', ['Next.js supplies the user interface; the Expo app hosts it in a WebView and supplies native camera, network, device and notification bridges. Connection and permission states affect availability.', 'Navigation exposes Home, Coach, Scan, Quests and Me. Session restoration and profile/onboarding determine what can be shown.']),
('2. Authentication and account sessions', ['Register and sign in through session endpoints. Email verification, verification codes, password reset and password change have request and confirmation paths.', 'Sessions can be refreshed or migrated, listed, revoked, logged out individually or logged out everywhere. Access-protected APIs use server-side authentication.']),
('3. Profile, onboarding and settings', ['Profile data includes personal measurements, goals, training preferences, health information and an emergency contact. User-facing forms update profile data; photo upload and removal are supported.', 'Settings include workout and safety-related preferences. The backend stores profile and settings against the account; reads and saves can fail and must surface errors.']),
('4. Home, goals and progress', ['The dashboard aggregates activity, nutrition and workout information, including missions and progress links. Goals and milestones summarize account-derived values.', 'Progress supports recording, listing and deleting measurements such as weight, waist and bench press. Values and strength estimates depend on user-provided records.']),
('5. Coach and exercise library', ['The Coach plan is derived from the profile and available exercise catalog. Users can browse the exercise library, search, filter by muscle and equipment, page through results, and open instructions and demonstrations where available.', 'Recent catalog queries and guide details use a bounded account-scoped device cache. The server remains authoritative. Administrator catalog operations are protected separately.']),
('6. Prepare and video analysis', ['Live camera readiness includes connection and coarse local scene checks. Camera permission and device support affect availability; a user can continue without the camera.', 'The upload flow previews MP4 or MOV locally and sends it only after Analyze video. The backend validates type, size and duration and forwards it to a configured pose provider. MediaPipe estimates landmarks and joint angles.', 'An optional selected squat or chest press can yield an experimental local movement-cycle count when signal checks pass. Gemini review, when configured and available, may supply a likely exercise, equipment, target muscles, estimated repetitions, observations, corrections and instructions.', 'Tracking coverage is not a form score. Correct-form repetitions, injury risk and overall accuracy are not validated. Provider failures can leave the review unavailable; the report includes retry and does not automatically modify the workout.']),
('7. Workout session and report', ['Create or recover an active workout, record sets with repetitions and weight, pause/resume, and complete the session. Saved account data and device-only drafts have different recovery behavior.', 'Completion creates a workout report based on saved workout data. Sharing may be unavailable in Expo Go. Workout history and summaries feed related dashboard and activity views.']),
('8. Nutrition, food scan and dietary plan', ['Add food through search or manual entry, or select/capture a food image and review an estimated scan before saving. Users can edit/delete meals, view today and history, and update water intake.', 'My Dietary Plan provides active targets, custom goals and meal allocation. Recommendations may use a configured AI provider and are reviewed before saving. Sample nutrition is explicitly separate from account data.']),
('9. Quests, activity and leaderboard', ['Activity tracks account-derived missions and engagement state. Quest screens display missions, streaks, levels and badges based on available data.', 'Leaderboard endpoints supply quest and strength views, subject to eligibility and privacy rules. Strength rankings use self-reported sets and estimated values rather than independently verified lifts.']),
('10. Notifications and reminders', ['The notification page lists system items, supports read/unread and mark-all-read, and stores reminder preferences. The mobile app includes device registration and notification permission handling.', 'Native notification presentation and delivery depend on device permission, provider configuration and deployment. A registered device or visible notification screen does not by itself prove production delivery.']),
('11. AI assistant and safety', ['Phiq chat sends a user question and relevant account summaries to the configured Gemini integration and returns a text response when available.', 'Safety endpoints create and resolve alerts. Inactivity monitoring and emergency-related behavior depend on configuration, device state, permissions and provider readiness; do not assume dispatch is guaranteed.']),
('12. Administration, privacy and backend services', ['Admin endpoints expose analytics and alert review and support exercise catalog management subject to authorization. The engagement screen includes a preview path; do not interpret preview data as live production analytics.', 'Account APIs support export, deletion and recovery flows. Supporting services include signed storage uploads/downloads, nutrition analysis jobs, synchronization snapshots, health and readiness endpoints. Their presence does not establish that every UI path uses them.']),
('13. Data, cache and dependencies', ['MongoDB stores account-associated server records. The device cache holds selected bounded resources, is scoped to account/API, expires data, refreshes and invalidates entries; it does not cover every page or guarantee offline writes.', 'External dependencies include configurable pose analysis, Gemini, food search/nutrition providers, media storage and push infrastructure. Availability, cost, permissions, data retention and deployment settings affect behavior. Secrets stay in backend configuration.']),
('Code evidence', ['Primary sources: backend/src/app.module.ts; backend/src/*/*.controller.ts; frontend/sections/Home, Coach, Scan, Quests Section and Me Section; frontend/lib/api.ts and deviceCache.mjs; mobile/App.tsx; pose-service/main.py.', 'Detailed flow evidence: frontend/sections/Coach/CoachSection.tsx and CameraCheck.tsx; frontend/sections/Scan/ScanSection.tsx; backend/src/pose/pose.service.ts and video-review.service.ts; backend/src/nutrition/nutrition.controller.ts; backend/src/notifications/notifications.controller.ts.'])]

pdfmetrics.registerFont(TTFont('Arial', 'C:/Windows/Fonts/arial.ttf'))
pdfmetrics.registerFont(TTFont('ArialBold', 'C:/Windows/Fonts/arialbd.ttf'))
styles_pdf=getSampleStyleSheet()
title=ParagraphStyle('TitlePQ',parent=styles_pdf['Title'],fontName='ArialBold',fontSize=22,leading=27,textColor=colors.HexColor('#102238'),spaceAfter=10)
head=ParagraphStyle('HeadingPQ',parent=styles_pdf['Heading2'],fontName='ArialBold',fontSize=13,leading=17,textColor=colors.HexColor('#17683b'),spaceBefore=13,spaceAfter=6)
body=ParagraphStyle('BodyPQ',parent=styles_pdf['BodyText'],fontName='Arial',fontSize=9.7,leading=14,spaceAfter=7,textColor=colors.HexColor('#243044'))
small=ParagraphStyle('SmallPQ',parent=body,fontSize=8,leading=11,textColor=colors.HexColor('#617087'))
doc=SimpleDocTemplate(str(OUT/'PhysiqueQuest_Features_and_Functionality.pdf'),pagesize=A4,leftMargin=20*mm,rightMargin=20*mm,topMargin=18*mm,bottomMargin=18*mm)
story=[Paragraph('PhysiqueQuest',title),Paragraph('Existing features and functionality',head),Paragraph('Implementation inventory | 29 October 2026',small),Spacer(1,6*mm)]
for heading, paragraphs in modules:
    story.append(KeepTogether([Paragraph(escape(heading),head),Paragraph(escape(paragraphs[0]),body)]))
    story.extend(Paragraph(escape(p),body) for p in paragraphs[1:])
def footer(canvas, document):
    canvas.setFont('Arial',8); canvas.setFillColor(colors.HexColor('#617087'))
    canvas.drawString(20*mm, 11*mm, 'PhysiqueQuest | implementation inventory')
    canvas.drawRightString(A4[0]-20*mm, 11*mm, str(document.page))
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(f'Created {len(pages)} draw.io pages and {len(modules)} inventory sections.')
